window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a798b61a15ae3f89"]={"versions": [{"id": "FIG-a798b61a15ae3f89", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Screenshot eines UML-Werkzeugfensters (Enterprise Architect, Fenster „Tagged Values“). Die Abbildung zeigt die Werkzeug-spezifische Konfiguration und Metadaten-Erfassung von Tagged Values für das UML-Attribut <code>DTC_CLASS</code> im Kontext des AUTOSAR Basic Software (BSW) UML Model Modeling Guide, speziell zur Modellierung von Bitfeldern bzw. Bitranges für Diagnostic Event Manager (DEM) Severity-Klassifizierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein UML-Attribut <code>DTC_CLASS</code> mit einer geordneten Sequenz indizierter Tagged-Value-Tripel (<code>name</code>, <code>value</code>, <code>description</code>), die hexadezimale Bitmasken und Beschreibungen für WWH-OBD-Schweregrade definieren:</p>\n<ul class=\"fig-list\"><li>Index 0: <code>value.0.name = DEM_SEVERITY_NO_SEVERITY</code>, <code>value.0.value = 0x00</code>, <code>value.0.description = No severity information available</code>\n</li><li>Index 1: <code>value.1.name = DEM_SEVERITY_WWHOBD_CLASS_N...</code>, <code>value.1.value = 0x01</code>, <code>value.1.description = No class information</code>\n</li><li>Index 2: <code>value.2.name = DEM_SEVERITY_WWHOBD_CLASS_A</code>, <code>value.2.value = 0x02</code>, <code>value.2.description = WWH-OBD Class A</code>\n</li><li>Index 3: <code>value.3.name = DEM_SEVERITY_WWHOBD_CLASS_B1</code>, <code>value.3.value = 0x04</code>, <code>value.3.description = WWH-OBD Class B1</code>\n</li><li>Index 4: <code>value.4.name = DEM_SEVERITY_WWHOBD_CLASS_B2</code>, <code>value.4.value = 0x08</code>, <code>value.4.description = WWH-OBD Class B2</code>\n</li><li>Index 5: <code>value.5.name = DEM_SEVERITY_WWHOBD_CLASS_C</code>, <code>value.5.value = 0x10</code>, <code>value.5.description = WWH-OBD Class C</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungskonstrukt ohne Laufzeitsequenz. Das Diagramm illustriert das Schema zur werkzeugseitigen Erfassung von Aufzählungswerten und Bitmasken innerhalb des UML-Profils zur Generierungszeit von BSW-Headerdateien und -Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsrichtlinie für BSW-UML-Modelle: Tagged Values müssen dem Schema <code>value.&lt;Index&gt;.&lt;name|value|description&gt;</code> folgen, um standardkonforme Bitranges für Bitmasken-Auswertungen im Dem-Modul abzubilden. Die Werte <code>0x00</code> bis <code>0x10</code> bilden binäre Flags bzw. diskrete Bitmuster für WWH-OBD-Emissionsklassen (Klasse A, B1, B2, C) und severity-lose Zustände ab.</p>"}, {"id": "FIG-129512066de05ba0", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Screenshot eines UML-Werkzeugfensters (Enterprise Architect, Fenster „Tagged Values“). Die Abbildung zeigt die Werkzeug-spezifische Konfiguration und Metadaten-Erfassung von Tagged Values für das UML-Attribut <code>DTC_CLASS</code> im Kontext des AUTOSAR Basic Software (BSW) UML Model Modeling Guide, speziell zur Modellierung von Bitfeldern bzw. Bitranges für Diagnostic Event Manager (DEM) Severity-Klassifizierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist ein UML-Attribut <code>DTC_CLASS</code> mit einer geordneten Sequenz indizierter Tagged-Value-Tripel (<code>name</code>, <code>value</code>, <code>description</code>), die hexadezimale Bitmasken und Beschreibungen für WWH-OBD-Schweregrade definieren:</p>\n<ul class=\"fig-list\"><li>Index 0: <code>value.0.name = DEM_SEVERITY_NO_SEVERITY</code>, <code>value.0.value = 0x00</code>, <code>value.0.description = No severity information available</code>\n</li><li>Index 1: <code>value.1.name = DEM_SEVERITY_WWHOBD_CLASS_N...</code>, <code>value.1.value = 0x01</code>, <code>value.1.description = No class information</code>\n</li><li>Index 2: <code>value.2.name = DEM_SEVERITY_WWHOBD_CLASS_A</code>, <code>value.2.value = 0x02</code>, <code>value.2.description = WWH-OBD Class A</code>\n</li><li>Index 3: <code>value.3.name = DEM_SEVERITY_WWHOBD_CLASS_B1</code>, <code>value.3.value = 0x04</code>, <code>value.3.description = WWH-OBD Class B1</code>\n</li><li>Index 4: <code>value.4.name = DEM_SEVERITY_WWHOBD_CLASS_B2</code>, <code>value.4.value = 0x08</code>, <code>value.4.description = WWH-OBD Class B2</code>\n</li><li>Index 5: <code>value.5.name = DEM_SEVERITY_WWHOBD_CLASS_C</code>, <code>value.5.value = 0x10</code>, <code>value.5.description = WWH-OBD Class C</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungskonstrukt ohne Laufzeitsequenz. Das Diagramm illustriert das Schema zur werkzeugseitigen Erfassung von Aufzählungswerten und Bitmasken innerhalb des UML-Profils zur Generierungszeit von BSW-Headerdateien und -Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsrichtlinie für BSW-UML-Modelle: Tagged Values müssen dem Schema <code>value.&lt;Index&gt;.&lt;name|value|description&gt;</code> folgen, um standardkonforme Bitranges für Bitmasken-Auswertungen im Dem-Modul abzubilden. Die Werte <code>0x00</code> bis <code>0x10</code> bilden binäre Flags bzw. diskrete Bitmuster für WWH-OBD-Emissionsklassen (Klasse A, B1, B2, C) und severity-lose Zustände ab.</p>"}], "trans": [{"from": "FIG-a798b61a15ae3f89", "to": "FIG-129512066de05ba0", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
